import subprocess, glob, os, sys, json
def symtest(dims, seed, nb):
    args=['/workspace/executable','-d',dims,'-s',str(seed)]
    for i in range(nb): args.append('python3 dumpstill.py %s'%('ABCDEFGHIJKLMNOP'[i]))
    for f in glob.glob('m_*.json')+glob.glob('*.hlt'):
        try: os.remove(f)
        except: pass
    try:
        p=subprocess.run(args, capture_output=True, text=True, timeout=60)
    except subprocess.TimeoutExpired:
        print(dims,'n=%d'%nb,'TIMEOUT'); return
    try:
        d=json.load(open('m_A.json'))
    except Exception as e:
        print(dims,'n=%d'%nb,'NOMAP', p.stdout[:200]); return
    w,h=d['w'],d['h']
    res=[]
    for field in ('prod','str'):
        A=d[field]
        found=[]
        for ax in ('y','x'):
            for sh in range(1,20):
                if ax=='y':
                    f=lambda y,x,sh=sh: A[y*w+x]==A[((y+sh)%h)*w+(w-1-x)]
                else:
                    f=lambda y,x,sh=sh: A[y*w+x]==A[(h-1-y)*w+((x+sh)%w)]
                if all(f(y,x) for y in range(h) for x in range(w)): found.append(ax+str(sh))
        res.append((field,found))
    own=[(i%w,i//w) for i,o in enumerate(d['own']) if o]
    print(dims,'n=%d'%nb, res, 'starts',own)
for dims in sys.argv[1:]:
    for nb in (2,):
        symtest(dims, 11, nb)
