def mt(seed):
    MT=[0]*624
    MT[0]=seed & 0xffffffff
    for i in range(1,624):
        MT[i]=(1812433253*(MT[i-1]^(MT[i-1]>>30))+i)&0xffffffff
    idx=624; out=[]
    while len(out)<2048:
        if idx>=624:
            for i in range(624):
                y=(MT[i]&0x80000000)|(MT[(i+1)%624]&0x7fffffff)
                MT[i]=MT[(i+397)%624]^(y>>1)^(0x9908b0df if y&1 else 0)
            idx=0
        y=MT[idx]; idx+=1
        y^= y>>11; y^=(y<<7)&0x9d2c5ac0; y^=(y<<15)&0xefc60000; y^=y>>18
        out.append(y)
    return out
def glibc(seed):
    r=[0]*344
    r[0]=seed & 0xffffffff
    for i in range(1,31):
        # r[i] = (16807 * r[i-1]) % 2147483647  (with signed handling)
        hi, lo = divmod(r[i-1], 127773)
        word = 16807*lo - 2836*hi
        if word < 0: word += 2147483647
        r[i]=word
    for i in range(31,34): r[i]=r[i-31]
    for i in range(34,344): r[i]=(r[i-31]+r[i-3])&0xffffffff
    out=[]
    for i in range(344,344+2048):
        r.append((r[i-31]+r[i-3])&0xffffffff)
        out.append(r[i]>>1)
    return out
