    for f in glob.glob('m_*.json'):
        try: os.remove(f)
        except: pass
    args=['/workspace/executable','-d',dims,'-s',str(seed)]
    for i in range(nb): args.append('python3 mapbot.py %s'%('ABCDEFGHIJKLMNOP'[i]))
    try: subprocess.run(args, capture_output=True, text=True, timeout=300)
    except Exception: return None
    try: return json.load(open('m_A.json'))
    except Exception: return None
import math
for s in (2,4,6,8,12,20,30,40):
    dims='%d %d'%(s,s)
    for seed in (1,2):
        d=getmap(dims,1,seed)
        if not d: print(dims,seed,'FAIL'); continue
        P=d['prod']; S=d['str']
        mp=sum(P)/len(P); ms=sum(S)/len(S)
        sp=(sum((v-mp)**2 for v in P)/len(P))**.5
        ss=(sum((v-ms)**2 for v in S)/len(S))**.5
        print('%2dx%-2d s%d: P mean %5.2f std %5.2f cv %.2f | S mean %6.1f std %6.1f cv %.2f'%(s,s,seed,mp,sp,sp/max(mp,.01),ms,ss,ss/max(ms,.01)))
EOF"}

