import subprocess, glob, os, json
def getmap(dims, nb, seed):
    for f in glob.glob('m_*.json'):
        try: os.remove(f)
        except: pass
    args=['/workspace/executable','-d',dims,'-s',str(seed)]
    for i in range(nb): args.append('python3 mapbot.py %s'%('ABCDEFGHIJKLMNOP'[i]))
    try: subprocess.run(args, capture_output=True, text=True, timeout=400)
    except Exception: return None
    try: return json.load(open('m_A.json'))
    except Exception: return None
def autoc(d, field, maxlag):
    w,h=d['w'],d['h']; A=d[field]
    m=sum(A)/len(A)
    den=sum((v-m)**2 for v in A)
    out=[]
    for dx in range(0,maxlag+1):
        row=[]
        for dy in range(0,maxlag+1):
            num=sum((A[y*w+x]-m)*(A[((y+dy)%h)*w+((x+dx)%w)]-m) for y in range(h) for x in range(w))
            row.append(round(num/den,3))
        out.append(row)
    return out
for s in (10,20,40):
    d=getmap('%d %d'%(s,s),1,1)
    if not d: print(s,'FAIL'); continue
    for field in ('prod','str'):
        ac=autoc(d,field,min(10,s//2))
        print('%dx%d %s'%(s,s,field))
        for i,row in enumerate(ac): print('   dx=%2d'%i, ' '.join('%5.2f'%v for v in row))
EOF"}

