import json
d=json.load(open('/tmp/t/cur.json'))
w,h=d['w'],d['h']
for field in ('prod','str'):
    A=d[field]
    # third differences along x
    runs={}
    for y in range(h):
        seq=[A[y*w+((x+3)%w)]-3*A[y*w+((x+2)%w)]+3*A[y*w+((x+1)%w)]-A[y*w+x] for x in range(w)]
        # run lengths of equal consecutive values
        cur=1
        for i in range(1,w):
            if seq[i]==seq[i-1]: cur+=1
            else:
                runs[cur]=runs.get(cur,0)+1; cur=1
        runs[cur]=runs.get(cur,0)+1
    print(field,'3rd-diff equal-run length histogram:', sorted(runs.items())[:12], 'total', sum(runs.values()))
EOF"}

