{"command": "cd /tmp/t && python3 - <<'EOF'
import sys; sys.path.insert(0,'/tmp/t')
import json, math
from fft import power
d=json.load(open('/tmp/t/cur.json'))
w,h=d['w'],d['h']
for field in ('prod','str'):
    P=power(d[field],w,h)
    tot=sum(sum(r) for r in P)
    # radial average
    byfreq={}
    for ky in range(h):
        for kx in range(w):
            f=math.sqrt(min(kx,w-kx)**2+min(ky,h-ky)**2)
            byfreq.setdefault(round(f,2),[]).append(P[ky][kx]/tot*100)
    print('---',field,'radial power spectrum (avg % and count)')
    for f in sorted(byfreq):
        v=byfreq[f]
        print('  freq %5.2f n=%3d avg %6.3f total %7.3f'%(f,len(v),sum(v)/len(v),sum(v)))
EOF"}

